  const modules = [
    M('risk-stop-evidence', 'Stops, sweeps, and what the evidence says', 'Separate a planned exit, a poor fill, and a story invented after the event.', 'orders', 'protect-trade',
      ['Classify an exit', 'Measure volatility honestly', 'Distinguish evidence from intent'], ['risk-stop-orders', 'risk-spoofing', 'risk-atr'], [
      L('risk-stop-evidence-1', 'A stop-out is not the same as liquidation', [
        S('Identify who initiated the exit', 'A stop-out usually means a protective order was triggered. A margin liquidation is a broker or venue reducing exposure because an account or position fails its collateral rules. A manual exit is a third mechanism. Traders sometimes use these words loosely; reconstruct the actual order and account records before diagnosing the problem.'),
        S('A trigger is not a fill guarantee', 'A stop-market order becomes eligible for market execution under the venue’s trigger convention. The resulting price can differ from the stop. A stop-limit constrains price but can remain unfilled. Neither order prevents a broker from enforcing its margin terms.', 'Buy 200 shares at $50 with a stop at $49. The planned price loss is $200. After a gap, an actual fill at $47.80 produces a $440 gross loss: 200 × ($50 − $47.80), before fees. This is an execution gap, not evidence by itself of forced margin liquidation.'),
        S('Keep an exit audit', 'Record the order type, trigger basis, intended stop, actual fill, quantity, fees, and broker reason code. Compare the records with the information available before the move. A larger-than-planned loss calls for a gap and liquidity review; a margin event calls for a collateral review. They can occur together, but they require different fixes.')
      ], 'Diagnose the exit mechanism before changing the strategy.', 'protect-trade', 'Place a protected paper trade, then compare the planned stop loss with the recorded fill. The stock lab does not simulate broker liquidation.', ['Name the order type and exit reason.', 'Calculate planned and realized loss using actual quantity and costs.']),
      L('risk-stop-evidence-2', 'A sweep describes price, not a trader’s intent', [
        S('State an observable event', 'A testable sweep description might be: price trades below a previously marked low, then a completed candle closes above that same level. Specify the level, minimum penetration, timeframe, and reclaim rule before looking at the outcome. The event can be counted even when no profitable reversal follows.'),
        S('Do not turn a wick into a culprit', 'A candle does not reveal all orders, trader identities, cancellations, or intent. News, ordinary liquidity-taking, clustered stops, and thin depth can produce similar shapes. CME’s disruptive-practice framework concerns conduct and intent; a screenshot alone cannot establish spoofing or prove that someone targeted your particular stop.'),
        S('Test the claim fairly', 'Keep every qualifying break-and-reclaim, including failed examples. Compare a written entry rule against a baseline, with the same costs and future-information restrictions. A few memorable reversals cannot tell you whether the setup works.', 'Suppose a sample contains 20 predefined sweeps: 7 reach the selected target first, 9 hit invalidation first, and 4 time out. Showing only the 7 targets hides 65% of the qualifying events. Keep timeouts and their actual exit costs in the result.'),
        S('Choose an actionable response', 'You can test a different confirmation rule, smaller size, or a no-trade condition. Naming an imagined adversary gives you no measurable rule to improve. Treat “stop hunt” as an unverified hypothesis unless there is evidence beyond the candle.')
      ], 'Describe the price sequence precisely; reserve claims about manipulation for evidence of conduct.', 'map-levels', 'Mark a prior level using revealed bars, then write a break-and-reclaim rule before advancing the replay.', ['Level and confirmation rule are fixed before the event.', 'Include a failed or unresolved example in the review.']),
      L('risk-stop-evidence-3', 'ATR is a volatility summary, not a shield', [
        S('Calculate the quantity correctly', 'True range is the largest of high minus low, absolute high minus previous close, and absolute low minus previous close. Average true range smooths earlier true ranges using a specified lookback and method. Record those settings; two indicators with different inputs need not match.', 'Previous close = 100, high = 103, low = 101. The three distances are 2, 3, and 1, so true range is 3. Using only high minus low misses the gap component.'),
        S('Separate scale from probability', 'ATR describes past movement size. It is not a forecast interval, a direction signal, or a boundary that price cannot cross. A stop at two ATR can still trigger, and a new event can exceed the recent volatility regime. No multiplier makes a stop impossible to “hunt.”'),
        S('Keep invalidation, sizing, and execution separate', 'First state where the trade idea fails. Use volatility as context, then calculate the quantity allowed by the chosen budget and costs. If a valid stop becomes wider, quantity generally falls. The distance also needs a stress test for a worse fill; choosing an ATR multiple does not provide that test.', 'With an illustrative $60 price-risk budget, a $1.50 stop distance allows 40 whole shares before costs. A $3 distance allows 20. Keeping 40 shares after widening the stop would double the planned price loss to $120.')
      ], 'ATR can inform scale; it cannot guarantee an exit price or a profitable stop location.', 'size-long', 'Calculate a size for two different stop distances with the same budget. Note that the lab tests share sizing, not an ATR trading edge.', ['Wider distance produces a smaller permitted quantity.', 'Name the lookback and one gap assumption omitted from the calculation.'])
    ], [
      Q('A protective sell stop triggers and fills below its stop price. There is no margin notice. What is supported by these facts?', 'A triggered stop had an adverse fill; margin liquidation has not been established.', ['The account was definitely liquidated for insufficient margin.', 'The exchange must have targeted this account.', 'A stop guarantees a refund of the difference.'], 'Use order records to classify the event. Stop price and execution price can differ; a margin liquidation requires separate evidence.'),
      Q('What can an OHLC wick below yesterday’s low prove by itself?', 'The recorded price traded below that low during the bar.', ['A specific institution saw your stop.', 'Every trader below the low was liquidated.', 'The next bar must reverse upward.'], 'OHLC establishes price observations. It does not reveal order ownership or intent, and it does not determine the next move.'),
      Q('Previous close is 80, high is 84, and low is 82. What is true range?', '4', ['2', '6', '82'], 'max(84 − 82, |84 − 80|, |82 − 80|) = max(2, 4, 2) = 4.'),
      Q('Which statement about a stop at two ATR is defensible?', 'It uses a historical volatility scale but can still trigger or fill worse.', ['It sits outside every possible stop hunt.', 'It has a known 95% probability of holding.', 'It removes the need to calculate quantity.'], 'ATR is not a probability distribution or loss guarantee. Its usefulness depends on the complete rule and the conditions being tested.'),
      Q('Ignoring costs, what happens to a 30-share position’s $60 planned loss if its $2 stop distance is widened to $3 without reducing size?', 'Planned price loss rises to $90.', ['Planned loss remains $60 because the entry did not change.', 'Planned loss falls to $40.', 'The trade becomes protected against gaps.'], 'Quantity × distance gives 30 × $3 = $90. A wider stop is an increase in exposure to loss unless size changes.')
    ]),
    M('risk-leverage-margin', 'Leverage, collateral, and forced exits', 'Understand the account rule that can close a trade before your plan does.', 'sizing', 'equity-check',
      ['Separate margin from loss risk', 'Read shared collateral', 'Check the current broker regime'], ['risk-margin-accounts', 'risk-margin-sale', 'risk-finra-26-10', 'risk-finra-intraday', 'risk-margin-modes', 'risk-mark-rules'], [
      L('risk-leverage-margin-1', 'Notional exposure is larger than the deposit', [
        S('Use the right denominator', 'For a simple linear position, effective leverage is absolute notional exposure divided by the equity supporting it. A small price change applies to the whole position. The collateral deposited to open a trade is not its maximum loss, and available buying power is not a sensible loss budget.'),
        S('Translate the move into account damage', 'A stress calculation should state direction, notional, equity, costs, and which quantities are held fixed. It is an illustration of sensitivity, not a venue liquidation formula.', 'A $10,000 equity pool supports $50,000 of long linear exposure: 5× leverage. A 2% adverse price move loses $1,000, or 10% of starting equity, before fees and funding. At 1× exposure the same move loses $200. A smaller deposit does not make the underlying price move smaller.'),
        S('Leave room for more than the initial calculation', 'Collateral requirements can change, and a broker can have stricter house requirements. Securities borrowing can create interest costs and losses beyond the initial deposit. Write both a planned exit loss and an adverse-execution scenario. If the stressed loss is unaffordable, a mechanically permitted order can still be inappropriate.', null, ['Verify the product’s multiplier and settlement currency.', 'Include existing positions and orders in exposure.', 'Read the broker’s liquidation powers before funding an account.'])
      ], 'Margin permits exposure; it does not define how much you can afford to lose.', 'equity-check', 'Use the equity lab to reconcile open P&L. Calculate the 5× example separately because the replay account does not implement leverage.', ['Calculate both dollar P&L and percentage of supporting equity.', 'Identify at least one cost excluded from the simple sensitivity model.']),
      L('risk-leverage-margin-2', 'Isolated, cross, maintenance, and mark price', [
        S('Read the collateral boundary', 'In an isolated arrangement, collateral is assigned to a particular position under the venue’s terms. In a cross arrangement, eligible collateral may support multiple positions. Exact transfer, auto-add, liquidation, and deficit rules vary. A mode label alone is not a promise that every possible loss is capped at an initial deposit.'),
        S('Watch the value used by the risk engine', 'Some derivatives venues evaluate margin with a calculated mark price rather than the last displayed trade. Collateral haircuts, maintenance tiers, funding, and other positions can also affect the test. A chart’s last price and a venue’s liquidation trigger may therefore disagree without an arithmetic error.'),
        S('Calculate a buffer, not an invented liquidation price', 'For a stated snapshot, equity minus required maintenance gives a cushion. To project a future threshold you would need the actual changing requirement, collateral valuation, price basis, fees, and liquidation method.', 'Under a fictional fixed-maintenance example, equity is $1,200 and maintenance is $1,000: cushion $200. A $40 fee reduces it to $160 even if market price is unchanged. In cross collateral, losses on a second position may consume the same cushion.'),
        S('Check the actual terms', 'The linked exchange documents demonstrate that these mechanisms are contract specific. They are not a recommendation of that venue or a rule for every jurisdiction. Never substitute a generic “100 divided by leverage” distance for the provider’s maintenance calculation.')
      ], 'Collateral scope and valuation rules matter as much as the leverage number.', 'complete-plan', 'Write the known equity and hypothetical maintenance buffer, then use the stock plan lab to practise a complete order plan without claiming it models liquidation.', ['Separate last trade price from a contractual mark-price trigger.', 'State whether other positions can consume the same collateral.']),
      L('risk-leverage-margin-3', 'Use current rules, then check the broker', [
        S('A dated rule change matters', 'FINRA Regulatory Notice 26-10 makes new U.S. intraday margin standards effective June 4, 2026, with a permitted transition through October 20, 2027. The new standards replace the former pattern-day-trader trade-count designation and $25,000 minimum. During the transition, a firm may still use the former approach. This is why a universal “every day trader needs $25,000” statement is inaccurate.'),
        S('Ask which regime applies to this account', 'Confirm your broker’s implementation date, account type, margin calculations, house requirements, and response to an intraday deficit. Cash-account payment and settlement rules are a separate subject. A rule about U.S. securities margin does not define futures, retail forex, crypto derivatives, or an overseas account.'),
        S('A margin call is not a reservation of time', 'A broker’s agreement can permit sales without first consulting you. An earlier notice or a displayed deadline does not necessarily guarantee the position will remain open. You cannot assume the broker will sell your preferred holding, wait for your personal stop, or accept a deposit that has not arrived.', 'A trader sees “fund by tomorrow” but the broker’s terms permit immediate risk reduction. Building today’s trade around a guaranteed overnight extension is unsound. The useful action is to verify the terms and reduce uncertainty about exposure and available funds.'),
        S('Keep the rule record current', 'Save the applicable broker document and date checked alongside the plan. Recheck after account changes and provider notices. Course completion does not override a broker’s approval or a product restriction.')
      ], 'Check the account’s current regime and house terms; a historical rule summary is not enough.', 'review-trade', 'Draft a broker-rule checklist beside the review lab: regime, account type, maintenance, liquidation rights, and date verified.', ['Include the June 2026 effective date and October 2027 transition context.', 'Avoid applying a U.S. securities rule to every product or account.'])
    ], [
      Q('$8,000 equity supports $40,000 linear long exposure. What is the gross equity effect of a 3% adverse move?', 'A $1,200 loss, or 15% of starting equity.', ['A $240 loss because only the deposit moves.', 'A $1,200 loss, or 3% of equity.', 'A guaranteed liquidation at exactly 3%.'], '$40,000 × 0.03 = $1,200; $1,200 ÷ $8,000 = 15%. Actual margin enforcement requires additional contractual inputs.'),
      Q('What can happen when two losing positions share cross collateral?', 'Both can reduce the same collateral pool.', ['Each loss is automatically limited to its original order fee.', 'The profitable position is legally immune from liquidation.', 'Their market risks cancel because there are two trades.'], 'Cross collateral changes how funds support positions. It does not make correlated losses disappear.'),
      Q('Why might a derivatives liquidation occur when the chart’s last trade has not touched a displayed estimate?', 'The venue may use a mark price and changing margin inputs.', ['Liquidation always uses the chart candle close.', 'A stop order legally prohibits liquidation.', 'All venues use one fixed global formula.'], 'The venue’s actual rules may use mark prices, tiers, fees, collateral adjustments, and other exposure. A generic estimate omits these inputs.'),
      Q('Which U.S. day-trading margin statement is current as of the source check?', 'FINRA’s new standards are effective June 4, 2026, with transition permitted through October 20, 2027; verify the firm’s regime.', ['Every account everywhere permanently requires $25,000.', 'All firms were required to switch on the first effective day.', 'Cash, futures, and crypto accounts all use the same FINRA rule.'], 'Regulatory Notice 26-10 distinguishes the effective date from the transition period. Applicability depends on the account, product, and firm.'),
      Q('What is the sound interpretation of a broker’s margin-call message?', 'Read the agreement; a message does not necessarily prevent earlier forced sales.', ['It always guarantees the position stays open until your preferred deadline.', 'You always choose which asset is sold.', 'A personal stop exempts the account from maintenance.'], 'Broker agreements can permit immediate sales and higher house requirements. Confirm the terms instead of relying on an assumed grace period.')
    ]),
    M('risk-portfolio', 'One account, many connected exposures', 'Combine positions, pending orders, and common shocks before sizing the next trade.', 'sizing', 'complete-plan',
      ['Aggregate planned loss', 'Distinguish gross and net exposure', 'Stress correlated positions'], ['risk-concentration', 'risk-liquidity', 'risk-margin-accounts', 'risk-online-orders', 'risk-trade-lifecycle'], [
      L('risk-portfolio-1', 'Three tickets can be one large bet', [
        S('Group by the driver of risk', 'Positions in related companies, a sector fund, and an index may react to the same news. Different tickers are not proof of diversification. Look through fund holdings, business exposure, and shared event times. Correlation estimates can change, particularly when markets become stressed.'),
        S('Add the commitments before entering', 'List the planned loss on every open position and any order that could become active. The sum is a useful planning measure under the stated fill assumptions. It is not a worst-case guarantee: stops can slip and several positions can gap together.', 'Three trades each plan to lose $120 on a $20,000 account. Combined planned loss is $360, or 1.8% of equity. In a deliberately harsher scenario where each loses twice its plan, damage is $720, or 3.6%, before additional costs. Calling each trade “small” hides the shared account result.'),
        S('Use a joint scenario', 'Ask what a sector shock, broad market gap, or sudden liquidity withdrawal would do to all positions at once. Include the cash needed to close or hedge. A common-risk limit can be tighter than the account-wide limit; neither number is universally safe. If no reasonable joint loss estimate is affordable, reduce exposure or skip the additional trade.')
      ], 'Size the account’s combined decision, not just the next ticket.', 'complete-plan', 'Create a three-position risk table on paper, then use the plan lab for one component. The lab’s single-position account does not model portfolio correlation.', ['Add all planned losses before calculating the account percentage.', 'Include one joint gap scenario with larger losses.']),
      L('risk-portfolio-2', 'Net zero does not mean risk zero', [
        S('Calculate both gross and net', 'Gross exposure adds absolute position values. Signed net exposure subtracts shorts from longs. The two numbers answer different questions. Low net exposure can coexist with large gross exposure, financing costs, and instrument-specific losses.'),
        S('Check what the hedge actually matches', 'A hedge can differ in sector, quantity, beta, currency, expiry, or trading hours. The difference between related instruments can move against you; this is a form of basis risk. A position that offsets a broad market move may not offset company-specific news.', 'Long $20,000 of a technology stock and short $20,000 of an industrial stock produces $40,000 gross exposure and $0 signed net exposure. If the long falls 4% while the short rises 3%, gross loss is $800 + $600 = $1,400, before costs. The equal notionals did not create a risk-free trade.'),
        S('Look inside the basket', 'An ETF can contain shares already held directly. Count overlapping holdings when the concentration matters to the plan. A fund name or a large number of line items does not tell you how independent the economic exposures are. Document the specific risk the hedge is intended to reduce and the risks it leaves behind.')
      ], 'A hedge is a specific offset with residual risks, not a general guarantee.', 'equity-check', 'Compute gross and net exposure for the two-position example, then reconcile a single open position in the equity lab.', ['Show both exposure numbers.', 'Calculate a scenario in which both legs lose money.']),
      L('risk-portfolio-3', 'Pending orders and liquidity consume capacity', [
        S('Count what can still happen', 'A working entry order may fill while you are deciding on another trade. A cancellation request is not a confirmed cancellation. Include uncertain orders in a conservative capacity check until the broker establishes their status. Otherwise, several individually acceptable orders can create an unwanted combined position.'),
        S('Model the exit, not only the entry', 'A displayed quote or a past volume total does not guarantee enough liquidity at your required price. Depth, spread, order size, volatility, and available routes affect execution. A hedge that becomes difficult to trade may stop doing the job when it is most needed.'),
        S('Build a small exposure ledger', 'Before a new order, list position, quantity, planned exit loss, stressed exit loss, shared risk driver, and status. Reserve capacity for working orders. Reconcile fills and cancellations before reusing that capacity.', 'The account allows an illustrative $250 of combined planned loss. An open trade uses $110 and an unconfirmed-cancel entry could use $90. Only $50 remains under this planning rule, not $140. A new $80 plan exceeds the limit unless the cancellation is confirmed or another exposure changes.'),
        S('Allow a genuine no-trade result', 'The right result of a capacity check can be no new order. Enlarging the account limit just because another setup appears prevents the limit from serving its purpose.')
      ], 'Uncertain order status and difficult exits belong in the risk calculation.', 'wait-trigger', 'Practise waiting while maintaining a written open-and-pending risk ledger; advance only after the stated condition is met.', ['Count pending risk until cancellation is confirmed.', 'Explain how an exit-liquidity shock could exceed the planned budget.'])
    ], [
      Q('Four related positions each plan a $75 loss. What is their combined planned loss before gap effects?', '$300', ['$75 because the tickers differ', '$150 because two can hedge the others automatically', '$0 if each has a stop'], 'The planning sum is 4 × $75 = $300. Correlation and worse fills can make the realized loss larger.'),
      Q('Long $12,000 and short $9,000 gives which exposure pair?', '$21,000 gross and $3,000 net long.', ['$3,000 gross and $21,000 net.', '$12,000 gross and no net exposure.', '$0 exposure because both directions are present.'], 'Gross adds absolute values: 12,000 + 9,000. Signed net subtracts: 12,000 − 9,000.'),
      Q('Why can a stock plus a sector ETF be concentrated?', 'The ETF may own the same stock and share its sector risk.', ['An ETF always eliminates every company and sector risk.', 'Two order tickets must be independent.', 'A different ticker guarantees negative correlation.'], 'Look through holdings and economic drivers. Diversification depends on the exposures, not the count of symbols.'),
      Q('An entry cancellation has been requested but not confirmed. How should a conservative risk ledger treat it?', 'Keep its possible fill in committed exposure until status is established.', ['Immediately assume the order can never fill.', 'Place another identical order to check the connection.', 'Delete it from the account record.'], 'A request may arrive after an order has filled. Reconcile actual order status before freeing capacity or sending a replacement.'),
      Q('A hedge matches broad market direction but differs in sector and trading hours. What remains?', 'Residual basis, event, and execution risk.', ['A legally guaranteed flat outcome.', 'No need to measure gross exposure.', 'A fixed profit equal to the spread.'], 'A hedge reduces a defined risk only to the extent its behavior and execution match the exposure being hedged.')
    ]),
    M('risk-drawdown', 'Drawdowns, practical ruin, and doubling down', 'See how losses compound and why recovery pressure can make the damage worse.', 'expectancy', 'equity-check',
      ['Calculate recovery burden', 'Stress losing sequences', 'Recognize averaging and martingale exposure'], ['risk-controlling', 'risk-two-percent', 'risk-resilience'], [
      L('risk-drawdown-1', 'Recovery uses a smaller denominator', [
        S('Measure from the relevant peak', 'Drawdown measures the fall from an equity peak to a later trough. Use equity that includes open P&L under a consistent convention, not only winning withdrawals or a selected subset of trades. Track deposits and withdrawals separately so external cash does not masquerade as strategy performance.'),
        S('Calculate the recovery requirement', 'If a fraction d of peak equity is lost, the gain required to recover is d divided by (1 − d). This is arithmetic, not a forecast that recovery will occur. The required percentage becomes much larger as the remaining capital shrinks.', 'A fall from $10,000 to $8,000 loses 20%. The $2,000 recovery now starts from $8,000, so it requires 25%. A 40% drawdown leaves $6,000 and requires $4,000 ÷ $6,000 = 66.67% to return to the peak.'),
        S('Do not turn a high-water mark into a deadline', 'The previous peak does not create an obligation for the market to repay you. “I need to recover this week” changes the objective from following a tested process to meeting an arbitrary cash target. Review affordability and the process before considering more exposure.'),
        S('Distinguish a deposit from performance', 'If the $8,000 account receives a $2,000 deposit, the balance is restored but the trading loss remains. Keep a cash-flow-adjusted record for performance and a separate current-equity record for risk capacity.')
      ], 'A drawdown changes the capital base; chasing the former peak does not change the math.', 'equity-check', 'Reconcile an equity loss, calculate the recovery percentage, and record any deposit separately from trading P&L.', ['Use remaining equity as the recovery denominator.', 'Distinguish trading gains from outside cash added.']),
      L('risk-drawdown-2', 'A risk percentage is not a survival guarantee', [
        S('Define failure before estimating it', 'Practical ruin can mean falling below a required cash reserve, minimum tradable size, margin threshold, or personal affordability limit. It need not mean a balance of zero. A meaningful risk-of-ruin calculation needs a stated failure boundary and defensible assumptions about outcomes, dependence, costs, and changing conditions.'),
        S('Stress a sequence without calling it a probability', 'If each loss is exactly a fraction f of then-current equity, remaining equity after n losses is starting equity × (1 − f)^n. This deterministic model excludes gaps and extra costs. It shows sensitivity to a chosen fraction; it does not tell you how likely that sequence is.', 'Starting at $10,000, ten losses of 2% of current equity leave about $8,170.73: an 18.29% drawdown. Ten fixed $200 losses instead leave $8,000. Neither result establishes that a 2% budget is safe for this trader.'),
        S('Avoid a misleading universal rule', 'CME’s educational 2% discussion explicitly describes the threshold as arbitrary. Appropriate capacity depends on the loss distribution, correlated exposure, livelihood needs, capital, product, and execution uncertainty. A smaller fraction can still be unaffordable or based on an unprofitable method.'),
        S('Respect the probability assumptions', 'Six losses in one specified block have probability 0.5^6 only if losses are independent and each has probability 0.5. That 1.5625% number is not the chance of a six-loss run somewhere in a year, and it is not the probability of account ruin.')
      ], 'Label a losing-streak calculation as a scenario, and state what would count as failure.', 'handle-loss', 'Use a losing replay outcome to practise closing and recording the loss. Separately stress ten losses under a chosen fraction and a stated practical floor.', ['Label the calculation as deterministic, not a ruin forecast.', 'State one reason the independent, constant-probability assumption could fail.']),
      L('risk-drawdown-3', 'A lower average entry can mean a larger loss', [
        S('Follow total quantity and total dollars', 'Averaging into a position lowers the average price of a long when the added fill is lower. It also increases quantity. Whether the total trade is acceptable depends on a plan made before the additions, a combined invalidation, available capital, and a total loss limit. A lower average entry alone is not risk reduction.'),
        S('Compare the same final price', 'Calculate the combined result at a common exit rather than celebrating that the break-even price moved closer.', 'Buy 100 shares at $50, then 100 more at $45. Average entry becomes $47.50. If all 200 exit at $42, gross loss is $1,100. Keeping only the original 100 shares to $42 would lose $800. The average entry improved while the dollar loss increased.'),
        S('Understand the capital demand of doubling', 'A martingale raises the next stake after a loss in an attempt to recover earlier losses. Finite capital, limits, costs, and adverse streaks prevent the imagined unlimited sequence. The recovery goal does not improve the next trade’s probability.', 'Doubling loss stakes of $100, $200, $400, $800, and $1,600 consumes $3,100. A $5,000 account then has $1,900 before costs, less than the next $3,200 stake. The method runs out of room before an assumed inevitable win.'),
        S('Use a different review question', 'Ask whether the original reason remains valid and whether the combined stressed loss still fits a precommitted limit. Do not add size solely because the position is losing or because you want the exit to feel less painful.')
      ], 'Recalculate total exposure after every addition; a cheaper average is not a smaller risk.', 'size-long', 'Calculate the two-entry average and combined loss on paper, then practise sizing one planned position without adding to a losing trade.', ['Compute total quantity and dollar loss, not just average entry.', 'Show where the doubling sequence exceeds finite capital.'])
    ], [
      Q('An account falls 25% from $12,000 to $9,000. What gain returns it to $12,000?', '33.33% of the remaining account, approximately.', ['25%', '20%', '75%'], '$3,000 ÷ $9,000 = 33.33%. Loss and recovery percentages use different starting values.'),
      Q('What does a table of ten exact 1% losses demonstrate?', 'A deterministic scenario under its stated assumptions.', ['The probability that your next ten trades all lose.', 'Proof that 1% risk is safe for everyone.', 'A complete liquidation-price model.'], 'The table describes a selected sequence. It does not estimate outcome probabilities, gaps, or all account constraints.'),
      Q('Why is 0.5^6 not automatically a yearly risk-of-ruin estimate?', 'It describes one specified six-loss block under independence and a constant 50% loss probability.', ['Because losses can never be consecutive.', 'Because all trading outcomes are independent.', 'Because every six-loss run causes a zero balance.'], 'A year contains many possible runs, outcomes can be dependent, and ruin needs a separate boundary and capital model.'),
      Q('Buy 10 shares at $60 and 10 at $50, then exit all at $45. What is gross loss?', '$200', ['$100', '$150', '$50'], 'Total cost is $1,100 and exit proceeds are $900: loss $200. The $55 average does not remove the added exposure.'),
      Q('Which reason alone is insufficient to increase the next position size?', 'I need the next winner to recover the previous loss.', ['The prewritten plan specifies the quantity within a verified combined limit.', 'The contract multiplier and permitted increment were checked.', 'The stressed loss remains inside the chosen capacity.'], 'A recovery wish changes neither the next trade’s probability nor the account’s ability to absorb a loss.')
    ]),
    M('risk-futures-forex', 'Futures and forex: learn the contract first', 'Translate ticks, settlement, currency units, and dealer terms into dollars at risk.', 'sizing', 'size-long',
      ['Use contract value', 'Understand variation margin', 'Translate FX units and costs'], ['risk-futures-margin', 'risk-futures-purpose', 'risk-futures-ticks', 'risk-forex-dealer', 'risk-forex-individuals'], [
      L('risk-futures-forex-1', 'A futures tick has a dollar value', [
        S('Read the specification before sizing', 'A futures contract defines an underlying, contract quantity or multiplier, tick increment, expiry, settlement method, and trading schedule. Similar names do not guarantee the same exposure. Micro and larger contracts can have different tick values and costs. Verify the current specification rather than inferring it from a chart price.'),
        S('Translate distance into money', 'For a linear contract with a known tick value, planned price loss equals stop distance in ticks × dollars per tick × number of contracts. Round quantity down to a permitted whole-contract increment and add costs. A broker’s opening margin is a separate constraint.', 'A fictional contract has a $2.50 tick value. A 12-tick stop implies $30 price loss per contract. Three contracts imply $90 before commissions and adverse fills. If the budget including costs is $90, three contracts may already be too many.'),
        S('Account for the contract ending', 'Cash settlement and physical delivery create different obligations. A continuous historical chart can splice contracts and may not equal an executable contract price. Know the actual contract month, broker close-out requirements, and relevant expiry or delivery dates. Avoid assuming that a “day trade” can never become an overnight obligation after a disruption.'),
        S('Keep the simulator boundary visible', scope)
      ], 'Contract size and tick value translate a chart move into an account result.', 'size-long', 'Work the fictional futures quantity on paper, then use the share-sizing lab to practise the budget-distance relationship. Do not use the share quantity as a futures contract count.', ['Include tick value and whole-contract rounding.', 'Name the actual contract month and settlement method you would need to verify.']),
      L('risk-futures-forex-2', 'Performance bond and daily cash flows', [
        S('Futures margin is a performance bond', 'Futures margin supports contractual obligations rather than functioning as a down payment on the underlying asset. Initial and maintenance requirements are distinct; exchanges and brokers can change requirements. Futures positions are marked to market, with variation settlement moving gains and losses through the account.'),
        S('Plan for the required replenishment', 'Read the broker’s exact maintenance and restoration policy. Falling below maintenance can require more funds or risk reduction. Do not assume a margin notice gives enough time to transfer cash from elsewhere.', 'In a fictional contract, initial margin is $1,500 and maintenance is $1,200. Equity allocated to the position falls to $1,150. If the stated policy requires restoration to $1,500, the shortfall to restore is $350, not merely the $50 below maintenance.'),
        S('Separate solvency from a directional opinion', 'A trader can still believe the long-term thesis while being unable to meet an immediate cash obligation. The account must survive the path, not just a hypothetical eventual price. Include overnight moves, changed margin requirements, and several positions settling losses together in the cash plan.'),
        S('Record usable funds honestly', 'Funds in another bank, pending transfers, or an expected payout may not be available when required. A collateral plan should identify what is accessible under the broker’s timing and currency rules. Treat a missed funding deadline as an operational risk, not an invitation to increase the trade.')
      ], 'A position can fail because of cash-flow timing even before its longer-term thesis is resolved.', 'equity-check', 'Reconcile a paper mark-to-market change, then compute the fictional restoration amount separately.', ['Distinguish maintenance threshold from restoration target.', 'Identify when cash must actually be available under the stated policy.']),
      L('risk-futures-forex-3', 'Forex units, quote currency, and counterparty', [
        S('State the pair and the units', 'An FX quote expresses the price of a base currency in a quote currency. For a simple position, quantity in base units times the change in the quote produces P&L in quote currency. If the account uses another currency, conversion changes the account result. A “lot” label is incomplete without its unit size.'),
        S('Calculate before applying leverage', 'Begin with units, quote movement, direction, and settlement currency. Then add spread, commission, financing or rollover terms, and conversion.', 'Long 10,000 EUR at EUR/USD 1.1000 and close at 1.0960. The change is −0.0040 USD per EUR, so gross P&L is −$40. Leverage changes the equity needed to support those units, not this $40 calculation. A non-USD account also needs a stated conversion rate.'),
        S('Know who is on the other side', 'In retail over-the-counter forex, the dealer can be the counterparty and controls its offered platform and quotes under the agreement. This differs from trading an exchange-listed currency future. Check registration where required, withdrawal terms, execution policies, and dispute procedures rather than assuming all products called “forex” have the same protections.'),
        S('Do not overlook holding costs', 'Rollover and financing conventions differ by provider and date. A strategy that looks profitable before spread and holding charges can fail after them. A promotional leverage ratio is not a reason to use the maximum exposure.')
      ], 'Translate units into the account currency and verify the product’s counterparty and cost model.', 'size-short', 'Calculate the FX example on paper, then practise directional loss arithmetic in the stock short-sizing lab.', ['Label base, quote, and account currencies.', 'List spread and financing assumptions separately from price P&L.'])
    ], [
      Q('A fictional futures contract is $5 per tick. Two contracts lose 9 ticks. What is gross price loss?', '$90', ['$45', '$18', '$10'], '9 ticks × $5 × 2 contracts = $90, before costs and any difference between stop and actual fill.'),
      Q('What does futures initial margin represent?', 'A performance bond required to support the contract.', ['The maximum possible loss on every contract.', 'Ownership of the underlying asset with no further obligations.', 'The number of ticks in the stop.'], 'Margin permits the position under current requirements. Price losses, changed requirements, and contractual settlement remain relevant.'),
      Q('A stated policy requires restoring $900 equity to $1,300 initial margin after maintenance is breached. How much is required?', '$400', ['$100 regardless of policy', '$900', '$1,300'], 'The restoration target in the question is $1,300; $1,300 − $900 = $400. Actual policy must be verified rather than inferred.'),
      Q('Long 5,000 EUR in EUR/USD loses 0.0060 USD per EUR. What is gross P&L in USD?', '−$30', ['−$3', '−$300', '+$30'], '5,000 × (−0.0060) = −$30. Spread, financing, commission, and any account-currency conversion are additional.'),
      Q('Which question belongs before choosing a retail forex account?', 'Who is the counterparty, what registration applies, and what are execution and withdrawal terms?', ['Which advertised leverage ratio is largest?', 'Can I avoid checking unit size because the platform says one lot?', 'Will a familiar pair name guarantee exchange protections?'], 'Product structure, legal entity, account terms, and costs affect the risks. The label “forex” does not settle those questions.')
    ]),
    M('risk-options', 'Options: premium, nonlinear risk, and assignment', 'Learn why a correct stock forecast can still produce the wrong options outcome.', 'riskreward', 'complete-plan',
      ['Translate premium and multiplier', 'Recognize nonlinear sensitivity', 'Plan for exercise and assignment'], ['risk-options-odd', 'risk-options-document', 'risk-options-assignment', 'risk-options-expiry', 'risk-options-0dte', 'risk-options-greeks'], [
      L('risk-options-1', 'An option is a contract with an expiry', [
        S('Read the terms, not just the ticker', 'An option has a type, strike, expiry, exercise style, settlement method, and contract multiplier. Standard equity contracts often represent 100 shares, but adjusted contracts can differ. Verify the deliverable. A quoted premium is not always the total debit displayed by a beginner’s mental calculation.'),
        S('Translate the purchase into dollars', 'For a simple long option held without exercising into an underlying position, the premium paid can be lost in full, plus costs. Exercise can create a different position with different funding and market risks; do not carry the premium-only description across that transition.', 'Three fictional standard contracts cost $1.20 per share with a 100-share multiplier. Premium debit is 3 × 100 × $1.20 = $360 before fees. A 100% premium loss is $360, not $3.60. The stock moving by one dollar does not imply each option moves by one dollar.'),
        S('Use a complete position description', 'Write direction, contract identifiers, number of contracts, total debit or credit, known expiry obligations, and costs. For a short option, receiving premium creates obligations rather than a guaranteed profit. Naked short calls can have theoretically unlimited loss; other short structures also need product-specific risk calculations.'),
        S('Practise at the correct level', 'The stock replay does not supply an option chain, volatility surface, exercise processing, or options margin. Use its plan lab to practise explicit assumptions, while keeping the option arithmetic in a clearly labeled educational worksheet.')
      ], 'Convert the premium with the verified multiplier and distinguish the option from any resulting underlying position.', 'complete-plan', 'Write a complete option contract description and premium calculation on paper, then use the plan lab for the general planning routine.', ['Verify multiplier, expiry, exercise style, and settlement.', 'State when the premium-only loss description stops being sufficient.']),
      L('risk-options-2', 'Direction is only one input', [
        S('Separate the sensitivities', 'Delta describes local sensitivity to an underlying-price change; gamma describes how delta changes. Theta relates to passing time, and vega to implied-volatility changes. These are model sensitivities around stated conditions, not fixed promises. A larger move, changing volatility, or the approach of expiry can change them substantially.'),
        S('A correct direction can still lose money', 'A purchased call can lose value while the underlying rises if time decay or a decline in implied volatility outweighs the directional effect. A headline catalyst may be anticipated in the premium before it occurs. You must evaluate the option’s fill and later value, not award yourself a win because the stock forecast was right.', 'Pay $2.00 for one fictional 100-multiplier call. After the event, the stock is higher but the option can be sold for $1.50. The gross option loss is $50. The observed option price, not the stock’s positive percentage change, determines the trade result.'),
        S('Near-expiry exposure changes quickly', 'Short-dated and zero-days-to-expiry contracts leave little time for an adverse move to recover. Small underlying changes near a strike can sharply alter exposure. A stop based on an option quote may face wide spreads or poor fills. Do not treat a low dollar premium as proof of a small percentage risk.'),
        S('Choose a measurable review', 'Record underlying price, option bid and ask, time remaining, implied-volatility assumptions, actual fills, and costs. A stock-only historical chart cannot reconstruct this complete options result.')
      ], 'An options hypothesis must address price, time, volatility, and execution together.', 'review-trade', 'Review the fictional option loss separately from the stock move, then practise writing a fact-based trade review in the stock lab.', ['Use the option’s actual prices to calculate P&L.', 'Name two non-directional inputs omitted by a stock-only replay.']),
      L('risk-options-3', 'Assignment can change the position you hold', [
        S('Know when obligations can arrive', 'A short American-style option can be assigned before expiration when exercised. A short call can require delivery of shares; a short put can require purchase at the strike. Exact deliverables depend on the contract. A long option in another leg is not automatically exercised at the same moment to resolve every assignment.'),
        S('Understand the assumptions behind a spread diagram', 'A payoff diagram summarizes a specified intact position at a stated time, usually expiration. Execution, early assignment, exercise instructions, and an underlying position created between actions can complicate the path.', 'For a fictional intact $5-wide credit spread with a $1.20 credit and a 100 multiplier, the usual terminal loss bound is ($5 − $1.20) × 100 = $380 before costs, under the stated settlement assumptions. That diagram is not a guarantee against extra exposure from an unhandled assignment or a broken leg.'),
        S('Read the operational cutoffs', 'Exercise instructions, contrary instructions, broker deadlines, account resources, and automatic exercise procedures matter. Do not assume that an option a few cents in or out of the money will create precisely the position you expect. Broker actions near expiry can affect the exit.'),
        S('Plan the entire lifecycle', 'Before holding near expiration, specify the intended close or exercise action, the deadline and time zone, resources for delivery, and a way to verify the resulting position. If those obligations are unclear, the trade is not fully planned.')
      ], 'The risk review continues through exercise, assignment, and final position reconciliation.', 'protect-trade', 'Use the stock protection lab to practise explicit exit conditions. Separately write an options-expiry checklist; the lab does not process assignment.', ['Distinguish an intact spread payoff from an operational guarantee.', 'Identify the position that assignment could create and its funding need.'])
    ], [
      Q('Two contracts cost $2.40 each with a stated 100 multiplier. What is premium paid before fees?', '$480', ['$4.80', '$240', '$48'], '2 × $2.40 × 100 = $480. Always verify the multiplier and any adjusted deliverable.'),
      Q('A stock rises but a purchased call falls in value. Which explanation can fit?', 'Time and implied-volatility changes outweighed the directional effect.', ['A call must rise whenever the stock rises.', 'Option prices never reflect time.', 'The stock-only replay proves the option fill was wrong.'], 'An option has multiple changing inputs. The actual option fill and exit value determine its P&L.'),
      Q('What does a short American-style put assignment generally require under its contract?', 'Buying the specified underlying deliverable at the strike.', ['Receiving premium again with no obligation.', 'Automatically canceling every other position.', 'Waiting until after expiration in all cases.'], 'A short put creates a purchase obligation if assigned. The deliverable and exercise rules must be checked for the particular contract.'),
      Q('A fictional intact $4-wide credit spread collects $0.90 with a 100 multiplier. What is its usual terminal loss bound before costs under the stated assumptions?', '$310', ['$90', '$400', '$490'], '(4 − 0.90) × 100 = $310. Operational and assignment risks still require separate planning; the diagram is not a blanket guarantee.'),
      Q('Which item cannot be reconstructed reliably from an underlying stock OHLC chart alone?', 'The option’s historical bid-ask fills and implied-volatility path.', ['The stock bar’s recorded open.', 'The stock bar’s recorded low.', 'The stock bar’s timestamp.'], 'An options backtest needs contract and market data appropriate to the option. A stock-only simulator cannot supply missing option quotes and exercise events.')
    ]),
    M('risk-short-crypto', 'Short stock, crypto, and hidden carrying risks', 'Account for borrowing, funding, collateral value, and obligations beyond a chart move.', 'sizing', 'size-short',
      ['Measure short exposure', 'Distinguish spot from perpetuals', 'Stress collateral and carrying costs'], ['risk-short-sales', 'risk-crypto-risks', 'risk-mark-rules', 'risk-margin-modes', 'risk-crypto-custody'], [
      L('risk-short-crypto-1', 'A short stock is a borrowing arrangement', [
        S('Reverse the price exposure, then add the obligations', 'A stock short generally involves borrowing shares, selling them, and later buying shares to return. Gross P&L is quantity × (sale price − cover price). A price rise creates a loss. Because a stock’s price has no fixed upper bound, the theoretical short-sale loss is not limited to the initial proceeds.'),
        S('Calculate the actual cover', 'Do not confuse the cash received at the short sale with earned profit. It supports an open obligation to return the shares.', 'Short 50 shares at $40 and cover at $70. Gross P&L is 50 × ($40 − $70) = −$1,500. Borrow fees, commissions, and any dividend-related payment increase the cost. A stop intended at $45 would not guarantee a $250 maximum loss through a gap.'),
        S('Borrow availability can change', 'Borrowing terms, fees, recalls, and broker buy-in procedures matter. A position may become costly or be closed even if your chart thesis has not changed. A rising price combined with urgent demand to cover can worsen execution; calling the stock expensive does not limit that path.'),
        S('Keep a short-specific checklist', 'Verify locate or borrow requirements, current costs, corporate actions, liquidity, and the broker’s close-out terms. ReplayLab’s short button teaches directional P&L and orders; it does not establish real borrow availability or implement a live stock-loan contract.')
      ], 'A short position has a return obligation and changing costs, not just a reversed chart bet.', 'size-short', 'Size and close a paper short, then add a separate borrow-cost and adverse-gap note to the review.', ['Reverse the price subtraction correctly.', 'State that the simulator does not verify borrow or cap real short losses.']),
      L('risk-short-crypto-2', 'Spot and perpetual contracts are different exposures', [
        S('Name the product precisely', 'An unborrowed spot purchase, a margined spot position, a dated future, and a perpetual derivative have different obligations. A perpetual contract can involve periodic funding and a contractual mark-price process. The token name alone does not define the exposure, collateral currency, or protections.'),
        S('Read the funding convention', 'Funding can be paid or received depending on the contract and rate. Its interval, notional basis, and rate can change. Do not treat a displayed short-period rate as a promised return or casually multiply it into an annual yield without stating assumptions.', 'A fictional contract specifies that this long position pays 0.01% on $20,000 notional for the stated funding interval. Payment is $2. If there are three identical intervals, the total is $6, but future rates and notional are not guaranteed to stay fixed.'),
        S('Verify the P&L formula', 'Linear contracts settled in a quote currency differ from inverse or coin-margined contracts. If collateral is itself volatile, its account-currency value can fall as the position loses. Maintenance and liquidation may use a mark price rather than the last trade; a single chart is not the complete margin ledger.'),
        S('Keep availability and legal terms local', 'Providers, products, customer eligibility, and protections vary by jurisdiction. An educational example does not establish that a contract is available to you. Read the actual legal entity’s terms and avoid using leverage merely because the product advertises it.')
      ], 'Specify contract, collateral, price basis, funding, and jurisdiction before calculating exposure.', 'complete-plan', 'Write a hypothetical perpetual contract specification and funding calculation. Use the stock plan lab only for the transferable planning sequence.', ['Convert the stated percentage correctly for its stated interval.', 'Separate spot ownership from a derivative and its collateral obligations.']),
      L('risk-short-crypto-3', 'Collateral can move against you too', [
        S('Model both sides of the balance sheet', 'If a venue accepts a volatile asset as collateral, its value can fall while the trading position also loses. A haircut or revised collateral policy can reduce recognized value further. A token described as stable can still have market, redemption, reserve, issuer, and operational risks; do not equate a target price with guaranteed cash.'),
        S('Stress recognized value', 'Use the provider’s valuation method where known, and label an illustrative method when it is not. Separate a market-price fall from the additional effect of a haircut.', 'A fictional account holds 2 collateral units priced at $1,000 each. At a 10% haircut, recognized collateral is $1,800. If price falls to $800 and the haircut rises to 20%, recognized value becomes 2 × $800 × 0.80 = $1,280. That is a $520 reduction before any trading loss.'),
        S('Do not ignore access risk', 'Exchange outages, custody failure, and withdrawal restrictions can prevent a planned collateral transfer or exit. Keeping all contingency funds on the same failing venue may not provide a useful contingency. The right arrangement depends on settlement and custody needs, not only on a displayed yield.'),
        S('Distinguish product risk from custody risk', 'A correct market decision cannot recover a lost private key or force a failed custodian to make an immediate payment. Record where assets are held, who controls transfer authority, and which loss protections actually apply. Avoid assuming that a familiar financial brand covers every asset with the same protection.')
      ], 'Stress position P&L, collateral valuation, and access together.', 'equity-check', 'Calculate the fictional collateral decline separately, then use the equity lab to practise keeping open P&L in the account picture.', ['Apply both price and haircut changes.', 'Name an access risk that a stop order cannot solve.'])
    ], [
      Q('Short 20 shares at $30 and cover at $45. What is gross P&L?', '−$300', ['+$300', '−$900', '+$600'], '20 × (30 − 45) = −$300 before fees and borrowing costs. Sale proceeds are not realized profit.'),
      Q('Which statement about a real stock short is accurate?', 'Borrow costs and buy-in or recall risk can matter independently of the chart thesis.', ['The initial sale proceeds cap every possible loss.', 'A paper short button proves shares are borrowable.', 'Dividends can never create a payment obligation.'], 'A real short requires the broker’s borrowing arrangements and carries obligations that a simplified price replay omits.'),
      Q('A fictional long perpetual must pay 0.02% on $15,000 for one interval. How much is that payment?', '$3', ['$300', '$30', '$0.30'], '$15,000 × 0.0002 = $3 for the stated interval. It is not an annual rate or a guaranteed future payment.'),
      Q('Why should a linear P&L formula not be applied blindly to every crypto derivative?', 'Inverse or coin-margined contracts can use a different formula and collateral exposure.', ['All crypto derivatives use a fixed dollar loss per coin.', 'Funding always cancels trading losses.', 'The ticker alone supplies every contract term.'], 'Read the contract specification, settlement currency, and mark-price rules before calculating risk.'),
      Q('Two collateral units are $600 each with a 25% haircut. What recognized value does this fictional rule produce?', '$900', ['$1,200', '$300', '$1,500'], '2 × $600 × (1 − 0.25) = $900. Market value and recognized collateral value are different quantities.')
    ]),
    M('risk-market-events', 'Gaps, news, halts, and missing liquidity', 'Plan for moments when the price you want is not available to trade.', 'orders', 'wait-trigger',
      ['Stress event gaps', 'Understand halted markets', 'Calculate spread and partial-fill costs'], ['risk-stop-orders', 'risk-halts', 'risk-extended-hours', 'risk-liquidity', 'risk-trade-lifecycle'], [
      L('risk-market-events-1', 'A scheduled event changes the risk question', [
        S('Separate knowing the time from knowing the outcome', 'A scheduled earnings release or economic announcement gives you a time to plan around, not a known direction or bounded move. Unscheduled news can arrive without a calendar warning. The relevant question is whether you can tolerate the possible execution and price change, not whether your narrative sounds convincing.'),
        S('Check the actual clock and session', 'Verify the official event time, its time zone, and the instrument’s trading session. ReplayLab displays America/New_York time with the applicable daylight-saving offset. A daily bar is a calendar session summary, not evidence that an intraday event occurred at its displayed close. A fixed UTC offset can misplace seasonal events.'),
        S('Stress a discontinuous exit', 'A stop can trigger after price has already moved beyond it. Recalculate from a possible worse fill and include costs; do not use the stop level as a guaranteed boundary.', 'Buy 80 shares at $25, planned stop $24.50. Planned price loss is $40. A news gap followed by a $23.25 fill produces an actual gross loss of $140. The additional $100 is not removed by having written the original budget.'),
        S('Write the event rule before the event', 'Your research plan can prohibit new exposure, reduce existing exposure, or require a specific post-event condition. There is no universal number of minutes after news that makes trading safe. Test a rule with spreads and actual availability, and allow “skip” when the required information is missing.')
      ], 'A known announcement time does not create a known maximum loss.', 'wait-trigger', 'Write a no-entry or post-event condition before advancing a replay. Explain what the dataset cannot reveal about real news-time liquidity.', ['Use the correct date and time zone.', 'Calculate a loss from a worse fill instead of assuming the stop price.']),
      L('risk-market-events-2', 'A trading halt can freeze your exit', [
        S('A displayed price is not always executable', 'Trading can be halted or delayed for news, regulatory concerns, or volatility mechanisms. During a halt, the last price can remain on screen while normal execution is unavailable. A stop or market order is not a promise that the halted instrument can be sold immediately.'),
        S('Prepare for reopening uncertainty', 'The reopening process can establish a different price with a large imbalance. Order handling depends on the venue and broker. Check whether your orders remain active, are queued, rejected, or require action. Do not infer order status solely from a chart or a frozen P&L display.'),
        S('Understand what a price band does not insure', 'A pause or limit mechanism governs trading under specified rules. It does not reimburse account losses, guarantee a reopening price, or ensure an unrelated hedge will behave as intended. A derivative or correlated instrument that continues trading can introduce a new mismatch.', 'A stock last traded at $18 and is halted. Your long position is 100 shares from $20 with a planned stop at $19. Marking the screen at $18 shows a $200 gross loss, but it does not establish that you can exit there. A later $16 reopening fill would produce a $400 loss.'),
        S('Review exposure before the emergency', 'Position concentration and the consequences of being unable to trade matter before entry. During a disruption, prioritize verified status, documented instructions, and avoiding duplicate exposure over attempts to force an unavailable exit.')
      ], 'A halt interrupts the ability to act; the last quote is not a reserved exit.', 'handle-loss', 'Use the loss-handling lab for orderly trade review, then write a separate halt scenario explaining why the simulator’s next-candle fill is not a halt guarantee.', ['Distinguish a displayed mark from an executable price.', 'State how you would verify broker order status during a halt.']),
      L('risk-market-events-3', 'Spread, depth, and partial fills change the result', [
        S('Start with the tradable sides', 'A market buy generally interacts with available offers; a market sell with bids. The last trade can sit between them or be stale. A wide spread can create an immediate loss on a round trip even without a meaningful change in the underlying market. Extended-hours conditions can differ from the regular session.'),
        S('Calculate the actual average fill', 'An order may execute in several pieces at different prices. Use a quantity-weighted average, then reconcile all fees. A chart touch does not prove your limit order reached the front of the queue or had enough opposing quantity.', 'Buy 40 shares at $10.00 and 60 at $10.10. Total cost is $1,006, so average fill is $10.06. Selling all 100 at a $9.95 bid would return $995: an $11 gross loss before fees. Using the first $10.00 fill for all shares understates the cost.'),
        S('Choose the uncertainty deliberately', 'A limit order controls its permitted price but can miss or partially fill. A market order prioritizes access to available liquidity while accepting price uncertainty. A stop-limit during a fast decline can leave a position open. The better choice depends on the task and the acceptable failure mode.'),
        S('Reconcile the remaining quantity', 'After a partial fill, track filled quantity, unfilled working quantity, protection attached to the actual position, and cancellation status. Do not protect or reverse a guessed size. If the market cannot support the intended execution, reducing size or passing is a valid response.')
      ], 'Use actual weighted fills and remaining quantity; a visible touch is not a complete execution record.', 'protect-trade', 'Practise protecting the actual paper position, then calculate the two-price fill example separately because OHLC replay does not model a live order book.', ['Use a quantity-weighted average.', 'State the fill uncertainty of a limit or stop-limit order.'])
    ], [
      Q('A 50-share long enters at $40, with a stop at $39. Actual gap fill is $37.50. What is gross loss?', '$125', ['$50', '$75', '$2.50'], '50 × ($40 − $37.50) = $125. The original stop planned a $50 price loss, but the fill determines the realized result.'),
      Q('A stock is halted with a last price of $12. What does that quote establish?', 'The last recorded trade price, not an available immediate exit.', ['A guaranteed sale at $12 for every holder.', 'That all active orders have been canceled.', 'That the reopening must occur above $12.'], 'A halt can interrupt execution. Verify the market and order status; the next executable price can differ.'),
      Q('Buy 30 shares at $20 and 70 at $20.20. What is the quantity-weighted average fill?', '$20.14', ['$20.10', '$20.20', '$20.06'], '(30 × 20 + 70 × 20.20) ÷ 100 = $20.14. The unequal quantities matter.'),
      Q('Which statement about a stop-limit is accurate during a fast decline?', 'Its price constraint can leave the position unfilled and still exposed.', ['It always closes the full position at the stop.', 'It guarantees no loss beyond the stop.', 'It cancels all broker margin rules.'], 'A triggered limit order still needs a compatible execution. Price control trades off against the risk of no fill.'),
      Q('Which event policy is defensible?', 'A prewritten, tested condition that permits skipping when liquidity or information is inadequate.', ['Every announcement becomes safe exactly five minutes later.', 'A calendar event guarantees the direction.', 'A daily candle reconstructs every intraday fill.'], 'The rule should match the product, data, and execution conditions. A fixed universal waiting time cannot guarantee safety.')
    ]),
    M('risk-prop-rules', 'Prop evaluations and drawdown contracts', 'Read the loss floor, fee exposure, and payout conditions before chasing a target.', 'discipline', 'complete-plan',
      ['Compute a breach cushion', 'Distinguish trailing rules', 'Read program and payout terms'], ['risk-prop-example', 'risk-contracts', 'risk-nfa-basic'], [
      L('risk-prop-rules-1', 'The advertised account size is not your loss budget', [
        S('Identify what is actually being offered', 'A program may involve a paid simulation, an evaluation, a simulated performance account, or a later live relationship. These are not interchangeable. Read the legal agreement to identify the entity, whether trades are real, what payment buys, who owns funds, and how any payout becomes enforceable.'),
        S('Calculate the usable cushion', 'The nominal account label can be much larger than the distance to disqualification. Include fees and unrealized P&L if the contract does. Passing a profit target while violating another rule can still fail the program.', 'In a wholly fictional evaluation, starting equity is $50,000 and a breach occurs at or below a $48,000 floor. Initial cushion is $2,000. A $500 planned loss consumes one quarter of that cushion, not merely 1% of the advertised $50,000. A gap can consume more.'),
        S('Keep paid attempts in a separate cash budget', 'Evaluation charges, subscriptions, data fees, activation fees, and resets can create real cash losses even when the displayed account is simulated. Calculate total paid costs and payouts actually received. An optimistic possible future payout does not reimburse fees already spent.'),
        S('Compare the entire rulebook', 'Review permitted instruments, size limits, restricted times, prohibited methods, daily loss rules, total drawdown, consistency requirements, withdrawal conditions, and dispute terms. The linked provider page is an example of a particular rulebook, not a recommendation or a standard for all firms.')
      ], 'Treat the program as a contract with a narrow failure boundary and real fee exposure.', 'complete-plan', 'Write a fictional evaluation plan using the stated floor and a separate fee budget; practise the general plan sequence in the stock lab.', ['Calculate risk as a fraction of the remaining cushion.', 'Distinguish simulated account size from real money paid for attempts.']),
      L('risk-prop-rules-2', 'Trailing drawdown depends on what is measured', [
        S('Identify the reference and measurement time', 'A static floor stays tied to a defined starting value. A trailing floor rises with a specified high-water mark. That mark might use intraday equity, end-of-day balance, or another definition. Some rules stop trailing at a cap. These details change the cushion even when the trade history looks the same.'),
        S('Work two different fictional rules', 'The following numbers are original teaching rules, not any provider’s current offer. Both use a $2,000 trailing allowance, but the first updates only from end-of-day peaks while the second uses continuous intraday equity.', 'Starting equity is $50,000. Highest end-of-day equity is $51,000; an intraday peak reached $52,000. Current equity is $50,300. The first floor is $49,000 and cushion is $1,300. The continuous-equity floor is $50,000 and cushion is only $300. The faded open profit matters under the second rule.'),
        S('Do not move a ratcheting floor back down', 'Under a one-way trailing rule, later losses reduce current equity while the recorded floor stays at its earlier level. Recalculating the floor from the now-lower equity would invent room that the contract does not grant. Keep the high-water mark and current equity as separate fields.'),
        S('Check the exact breach convention', 'A rule can count touching a limit, crossing it, or a specific marked snapshot. Determine whether commissions, open P&L, daily resets, and data timing enter the test. A calculator using different conventions can show a false cushion.')
      ], 'You cannot calculate the drawdown cushion without the rule’s reference, timing, and breach convention.', 'equity-check', 'Calculate both fictional trailing floors, then practise reading current equity in the lab. The lab does not enforce a prop contract.', ['Keep the historical high-water mark separate from current equity.', 'State whether the rule counts unrealized intraday gains and touching the floor.']),
      L('risk-prop-rules-3', 'Payouts, daily resets, and terms can change capacity', [
        S('Calculate the account after the withdrawal', 'A payout can reduce usable equity, alter a floor, or trigger a different rule under the agreement. Do not assume the pre-payout risk budget survives. Ask what remains available to lose after all fees and any reset mechanics.', 'Under a fictional static $49,000 floor, current equity is $51,000. A permitted $1,500 withdrawal leaves $49,500 and only $500 of cushion. Keeping the old $1,000 trade budget would exceed that remaining room. Other programs may adjust the floor differently; the example is not a universal policy.'),
        S('Respect the daily boundary', 'If a daily loss rule exists, identify its time zone, reset time, starting reference, and whether it includes open losses and costs. Crossing midnight on your computer does not necessarily reset the program. Holding a trade across the provider’s reset can change the calculation.'),
        S('Verify the counterparty and the version', 'Save the terms accepted, the date, payment record, account type, and payout conditions. Research the actual legal entity and relevant registrations where applicable. A simulated evaluation business is not automatically the same as a regulated broker holding customer assets; a registration search must match the activity and jurisdiction.'),
        S('Put an end to repeated fee chasing', 'Choose an affordable total spending limit for research and practice before buying attempts. Another reset does not repair an untested method. A record of fees, failed rules, and money actually received gives a more honest result than a screenshot of simulated profits.')
      ], 'Recalculate capacity after every payout or rule change, and count real program costs.', 'review-trade', 'Review a fictional payout and rule breach alongside a paper-trade review. Record actual fees separately from simulated P&L.', ['Compute post-withdrawal equity and cushion.', 'Write the applicable reset time zone and retain the contract version.'])
    ], [
      Q('A fictional $100,000 evaluation breaches at $97,000. Before any gain or cost, what is its loss-floor cushion?', '$3,000', ['$100,000', '$97,000', '$1,000'], '$100,000 − $97,000 = $3,000. The displayed account size is not the amount you can lose before this stated breach.'),
      Q('A fictional continuous trailing rule uses peak equity $53,000 minus a $2,000 allowance. Current equity is $51,600. What is the cushion?', '$600', ['$2,000', '$1,600', '$3,000'], 'Floor = $51,000; current equity $51,600 leaves $600. The floor follows the prior peak under the rule in the question.'),
      Q('Why can two programs show different remaining risk after the same trades?', 'They may measure different peaks, open P&L, reset times, costs, and floor caps.', ['All programs must use the same legal drawdown formula.', 'Their nominal account labels uniquely determine the rule.', 'Withdrawals never affect risk capacity.'], 'Read the actual definitions. A generic trailing formula cannot substitute for the program’s complete terms.'),
      Q('A fictional account has $25,800 equity and a fixed $25,000 floor. A $600 withdrawal is allowed and does not move the floor. What remains?', '$200 of cushion.', ['$800 of cushion.', '$600 of cushion.', '$1,400 of cushion.'], 'Post-withdrawal equity is $25,200. Subtracting the unchanged $25,000 floor leaves $200 before other costs.'),
      Q('Which record is necessary to evaluate a paid challenge honestly?', 'Fees and resets paid, rules breached, and payouts actually received.', ['Only the largest simulated profit screenshot.', 'Only the advertised account size.', 'Only a possible payout that has not been approved.'], 'Real cash spending and enforceable payout conditions matter even when the trading environment is simulated.')
    ]),
    M('risk-operations', 'Outages, custody, and fraud defenses', 'Protect the ability to act and verify what happened when the platform cannot tell you.', 'orders', 'review-trade',
      ['Reconcile uncertain order status', 'Separate custody from market risk', 'Verify identity and claims'], ['risk-online-orders', 'risk-trade-lifecycle', 'risk-crypto-custody', 'risk-cftc-check', 'risk-nfa-basic', 'risk-ai-fraud', 'risk-pool-fraud'], [
      L('risk-operations-1', 'A missing confirmation is not a rejected order', [
        S('Treat uncertainty as exposure', 'A timeout can occur after an order reaches the broker. Repeated clicks can create duplicate orders if the platform did not reject the first one. Likewise, a cancel request may arrive after execution. Distinguish submitted, acknowledged, working, partially filled, filled, canceled, and rejected states using the broker’s record.'),
        S('Use a defined incident sequence', 'Stop sending replacements while the status is unknown. Check the official order and position records through an available channel, match order IDs and timestamps, and use the broker’s designated support or emergency process if needed. Do not rely on a separate chart feed as proof of broker order state.'),
        S('Reconcile before resuming', 'Record what you attempted, what was acknowledged, actual fills, remaining working quantity, and any protection still active. Then calculate the real position. A stale local display can show a flat account while a server-side order is live.', 'You intended to buy 10 shares. The first submission times out; a second is accepted. Later, both order IDs show 10-share fills. Actual exposure is 20 shares. Closing only the visible second 10-share lot leaves 10 shares open unless the position record confirms otherwise.'),
        S('Prepare the backup before the outage', 'Know the provider’s alternate access and contact methods and retain them independently of the failing app. Paper-test your recovery checklist. ReplayLab’s browser backup protects local practice data; it is not a broker disaster-recovery service and cannot verify a live account.')
      ], 'Unknown status is a reason to reconcile, not a reason to send the same order again.', 'review-trade', 'Write an incident log with two order IDs and reconcile the total position. Use the review lab to practise evidence-based explanation.', ['Do not equate a timeout with rejection or a request with confirmed cancellation.', 'Reconcile all fills and working orders before resuming.']),
      L('risk-operations-2', 'Custody and account security are separate risks', [
        S('Identify who controls the assets', 'Self-custody places private-key management with the holder. Third-party custody changes that responsibility but adds reliance on the custodian’s controls and terms. Loss of access, theft, insolvency, and market decline are different events. Protection for one does not imply reimbursement for the others.'),
        S('Protect transfer authority', 'Keep recovery phrases, private keys, passwords, and API secrets out of chat messages, screenshots, shared documents, and unofficial support channels. Use appropriate multi-factor authentication, unique credentials, and least-privilege access. Read-only access is preferable when the task only needs records; trading or withdrawal authority creates additional consequences.'),
        S('Verify the destination and the account type', 'Use independently reached official channels to check an address change, transfer request, legal entity, and custody terms. A convincing logo or a familiar app name does not establish that you reached the right account or service. Never assume that every asset within one app has identical legal protection.'),
        S('Plan an access drill', 'For a hypothetical account, document how to recover access without exposing secrets, how to recognize authorized devices, and how to revoke unwanted permissions. Keep the drill separate from trading decisions.', 'An analyst only needs transaction history to reconcile trades. Granting withdrawal-capable API access is unnecessary for that task. If a third party insists on a seed phrase to produce a report, stop the transfer of information and verify through the legitimate provider.')
      ], 'A trading edge cannot compensate for compromised credentials or misunderstood custody terms.', 'review-trade', 'Write a least-privilege records workflow and an account-access checklist; do not enter any real credentials into the lab.', ['Separate market-loss risk from access and custody risks.', 'Keep secrets out of the exercise and choose only necessary permissions.']),
      L('risk-operations-3', 'Verify the claim before paying or connecting', [
        S('Evaluate the promise and the business', 'Guaranteed returns, urgent payment demands, unverified performance screenshots, secret recovery fees, and claims that an AI system cannot lose are reasons to stop and investigate. A plausible interface is cheap to build. A testimonial or affiliate recommendation does not independently verify custody, execution, or performance.'),
        S('Check the exact identity', 'Use the relevant official registration and disciplinary databases, such as NFA BASIC for the activities it covers. Match legal names, registration numbers, domains, and contact details through an independent route. Registration is not an endorsement or a profit guarantee, and a database must be appropriate for the activity and jurisdiction.'),
        S('Demand an auditable record', 'Ask whether results are actual, hypothetical, selected, or net of all charges. Verify withdrawal terms and who holds funds. A high win rate without position size, losses, fees, and a complete sample cannot establish profitability. Do not send a new payment just to unlock an unverified balance.'),
        S('Create a stop condition for the relationship', 'If identity, funds control, or contractual rights cannot be established, decline the connection or payment. Preserve records through appropriate channels instead of engaging in a public accusation based only on suspicion.', 'A seller promises an AI bot will return 4% every day and asks for withdrawal-capable credentials. The decision is not to negotiate a slightly lower fee. The unsupported guarantee and unnecessary transfer authority require verification before any payment or connection.')
      ], 'Verify identity, authority, custody, and complete performance evidence; no technology removes market uncertainty.', 'wait-trigger', 'Practise a deliberate pause: write the missing evidence and the exact condition required before connecting a hypothetical service.', ['Match identity through an official, independently reached source.', 'Reject a guarantee as evidence of future performance.'])
    ], [
      Q('An order submission times out with no confirmed rejection. What is the strongest next action?', 'Verify order and position status before sending a replacement.', ['Submit the same order repeatedly until one screen responds.', 'Assume no order exists anywhere.', 'Close the browser and ignore the account.'], 'The order may have reached the broker before the response failed. Reconciliation prevents duplicate exposure.'),
      Q('A cancel request is pending. Which statement is accurate?', 'The order may still fill until its actual status is established.', ['It has necessarily been canceled.', 'Any later fill must be ignored.', 'The position can be safely deleted from records.'], 'A cancellation request and a confirmed cancellation are different events. The order may have executed first.'),
      Q('Which permission fits an app that only needs to read transaction history?', 'Read-only access limited to the records required.', ['Withdrawal authority by default.', 'A recovery phrase sent through chat.', 'Full trading authority because it might be useful later.'], 'Limit access to the task. Unnecessary authority creates consequences unrelated to the report being produced.'),
      Q('What does finding a matching registration establish?', 'Relevant registration information, not a guarantee of profit or protection for every activity.', ['That every product offered is risk-free.', 'That every screenshot is genuine.', 'That all future withdrawals are guaranteed.'], 'Match the exact entity and covered activity. Registration and disciplinary checks are useful evidence with specific limits.'),
      Q('A bot seller promises guaranteed daily gains and asks for your seed phrase. What is the defensible response?', 'Do not provide secrets or pay; verify the identity and claim through independent official channels.', ['Provide the phrase because the bot uses AI.', 'Pay a small recovery fee first to test the promise.', 'Assume the guarantee removes market risk.'], 'A secret gives control over assets, while an unsupported return guarantee supplies no reliable evidence. AI does not eliminate financial uncertainty.')
    ]),
    M('risk-research', 'Research that can survive an honest test', 'Avoid future information, selection bias, unrealistic fills, and attractive but fragile results.', 'expectancy', 'review-trade',
      ['Audit information timing', 'Control selection and costs', 'Evaluate uncertainty on unseen data'], ['risk-hypothetical', 'risk-system-claims', 'risk-promotional-guide'], [
      L('risk-research-1', 'Make the historical decision with historical information', [
        S('Audit when each input became available', 'A valid test uses the information a trader could have obtained at the decision time. A pivot that needs three later bars cannot trigger an entry at the original pivot bar. A revised economic series or end-of-day value must not appear early merely because the modern dataset contains it.'),
        S('Keep the universe honest', 'A list containing only today’s survivors can omit delisted, failed, or acquired instruments that belonged in the historical opportunity set. A social-media collection of successful charts selects outcomes before testing. Define the instruments, period, sessions, exclusions, and missing-data handling before judging performance.'),
        S('Label ambiguity rather than manufacturing precision', 'OHLC bars do not reveal the complete within-bar path or order queue. If stop and target both lie within one bar, the actual first touch may be unknown. Use a declared conservative policy, more suitable data, or an ambiguity category; do not always choose the profitable sequence.'),
        S('Perform a timing audit', 'For every input, write event time, data-availability time, decision time, and execution assumption.', 'A swing high at 10:00 is defined by two lower highs at 10:03 and 10:06. It can be confirmed only after the required 10:06 observation is available. A backtest selling the “confirmed” high at 10:00 has borrowed information from the future.')
      ], 'The test must know only what was available then, including the time required for confirmation.', 'identify-trend', 'Identify trend structure from revealed bars and mark a recent swing as provisional until the rule’s later evidence appears.', ['State when each confirmation becomes knowable.', 'Record an ambiguous bar outcome without choosing the winner by hindsight.']),
      L('risk-research-2', 'Costs and selection can erase the apparent edge', [
        S('Calculate net expectancy with consistent units', 'A simple average result combines win probability, average gain, loss probability, and average loss, then subtracts costs not already included. If the gains and losses are already net, subtracting costs again is an error. Win rate alone cannot establish an edge.'),
        S('Use an original worked example', 'Keep the initial risk unit R fixed under the declared convention so results remain comparable.', 'A hypothetical sample wins 40% of the time with average gross gain 2R and loses 60% with average gross loss 1R. Gross expectancy is 0.4 × 2 − 0.6 × 1 = 0.2R per trade. If additional average costs are 0.25R, net expectancy becomes −0.05R. A positive gross chart result has become a negative trading result.'),
        S('Count the experiments you tried', 'If you test many stop distances, indicators, sessions, and filters, the best historical combination benefits from selection. Reporting only the winner hides how many chances randomness had to look impressive. Keep an experiment log and freeze a rule version before evaluating untouched data.'),
        S('Stress the assumptions that make it work', 'Increase costs, delay entries, change a small parameter, and include less favorable periods. A rule that collapses under a tiny plausible change deserves more investigation. A high backtest score is not a reason to erase inconvenient fills or reclassify losing trades as exceptions.')
      ], 'Evaluate the net, selected process, including the unsuccessful experiments that led to it.', 'review-trade', 'Recalculate the gross-to-net example and review one paper trade’s actual fee and slippage entries.', ['State whether P&L inputs already include costs.', 'Log parameter changes instead of silently replacing a losing version.']),
      L('risk-research-3', 'Use unseen tests and acknowledge uncertainty', [
        S('Protect the evaluation sample', 'Development data helps define a rule. A holdout evaluates the frozen version. Once the holdout result influences a change, that data has become part of development for the new version. Use a new untouched evaluation or a predeclared walk-forward process rather than repeatedly calling the same inspected sample independent.'),
        S('Report more than an average', 'Record sample size, complete returns, costs, drawdown, losing sequences, ambiguous fills, and the environments represented. Trades from one day or one regime can be dependent. Simple uncertainty calculations that assume independent observations can understate the real uncertainty when outcomes cluster.'),
        S('Separate simulation from execution evidence', 'NFA and CFTC materials emphasize limitations of hypothetical results, including hindsight and real-world frictions. A replay cannot prove future fills, discipline under financial pressure, or future market behavior. A later shadow or observation phase can check operational assumptions without treating a backtest as a guaranteed income plan.'),
        S('Choose a decision rule before seeing the score', 'Define what evidence would justify further research, modification, or rejection. Allow rejection as a successful research outcome.', 'Suppose version A is frozen and fails its stated net-cost criterion on the holdout. Adding a filter that fixes those same losses creates version B. Version B needs a fresh evaluation; relabeling the repaired holdout as a clean pass would hide the selection step.')
      ], 'A useful test can reject a strategy; passing a limited test does not certify future profitability.', 'review-trade', 'Write a frozen-rule evaluation card and review a paper outcome against it without changing the criterion afterward.', ['Separate development and untouched evaluation periods.', 'Record sample and fill limitations alongside the score.'])
    ], [
      Q('A pivot requires two later bars to confirm. When can a rule first use it as confirmed?', 'After the required later observations are available.', ['At the original pivot timestamp using future bars.', 'Whenever the final chart makes it look obvious.', 'Before the high or low occurred.'], 'Confirmation has an information-availability time. Backdating it leaks future information into the decision.'),
      Q('A test includes only companies that still trade today. What risk needs investigation?', 'Survivorship bias from missing historical failures and removals.', ['A guarantee that all historical trades were executable.', 'The elimination of every data-quality issue.', 'Proof that the universe was known in advance.'], 'Today’s survivors may not represent the full opportunity set available during the historical period.'),
      Q('Gross expectancy is +0.15R and additional costs not yet included average 0.20R. What is net expectancy?', '−0.05R per trade.', ['+0.35R per trade.', '+0.15R per trade.', 'It must be positive because gross expectancy is positive.'], '0.15R − 0.20R = −0.05R. Include each cost exactly once.'),
      Q('You inspected a holdout, changed the rule to fix its losses, then retested it. What is that sample now?', 'Part of development for the revised rule.', ['An untouched independent test of the revised rule.', 'Proof of a permanent edge.', 'A reason to delete the first version.'], 'The observed outcomes influenced the revision. Fresh evaluation is needed to assess the new version without that selection.'),
      Q('An OHLC bar touches both stop and target but reveals no intrabar sequence. What is defensible?', 'Apply a declared ambiguity or conservative policy, or obtain suitable finer data.', ['Always count the target first.', 'Always infer the path from the candle color.', 'Delete only the ambiguous losing trades.'], 'OHLC alone does not establish every sequence. The handling policy should be declared before the outcome is selected.')
    ]),
    M('risk-recovery', 'After a loss: repair the process before the size', 'Turn an adverse outcome into a specific review and a controlled next decision.', 'discipline', 'handle-loss',
      ['Classify process failures', 'Define session loss controls', 'Design a staged return to practice'], ['risk-emotions', 'risk-day-disclosure', 'risk-resilience', 'risk-controlling'], [
      L('risk-recovery-1', 'Separate a planned loss from a broken process', [
        S('Use two scores', 'An unfavorable outcome can come from a correctly executed plan; a profitable trade can still violate the plan. Score the financial result and process adherence separately. A review that forgives every winning violation teaches the wrong habit and makes a later loss harder to diagnose.'),
        S('Classify the cause without rewriting history', 'Possible categories include a planned strategy loss, an entry or sizing error, an execution shock, an operational failure, and a rule that was never sufficiently defined. More than one can apply. Use the pre-trade plan, timestamps, orders, fills, and costs rather than a chart annotated after the outcome.'),
        S('Make the repair match the mechanism', 'A wrong quantity calls for a quantity or confirmation control. An unplanned gap calls for exposure and event review. A strategy loss inside the model belongs in the full sample rather than being deleted. Changing every rule after one loss prevents any stable evaluation.', 'A trade planned 25 shares, but an accidental extra click created 50. The market then hit the intended stop. The directional outcome was a planned loss; the doubled quantity was a separate execution-control failure. Labeling the whole event “bad strategy” would miss the repair.'),
        S('Preserve the original evidence', 'Save the initial plan and records before editing an explanation. Write the observed failure, its consequence, and one testable correction. “Be more disciplined” is too vague to verify; “confirm filled quantity before adding protection” identifies an action.')
      ], 'Review what was controllable without pretending that every loss proves a mistake.', 'handle-loss', 'Close and review a losing paper trade. Give it separate outcome and adherence scores with one evidence-based correction.', ['Keep the pre-trade plan unchanged in the record.', 'Tie the proposed correction to the observed cause.']),
      L('risk-recovery-2', 'A session stop needs an exact definition', [
        S('Decide what the limit measures', 'A session control might track realized net P&L, total equity change including open P&L, or another predeclared measure. Identify starting equity, external cash flows, fees, time zone, and reset time. A realized-only display can hide a large open loss; a boundary that changes after each loss is not a stable rule.'),
        S('Count what is already used', 'Before another entry, compare remaining capacity with the proposed loss, existing exposure, and a stress allowance. A session control is a decision rule, not a guarantee that fills will stop exactly at the boundary.', 'Under a fictional $300 session loss limit that includes open P&L, closed net loss is $180 and the open position is down $90. Current loss is $270 and nominal room is $30. A proposed additional $70 planned loss already exceeds that room before gap risk or further movement in the open position.'),
        S('Write the action at the boundary', 'Specify whether the rule blocks new orders, reduces or closes exposure, cancels entries, or ends the session. Account for actual position status and confirmed cancellations. A stop button that only disables new entries while a losing position remains open does not cap total loss.'),
        S('Choose the number from capacity and evidence', 'There is no universally safe daily percentage or number of losing trades. The rule must fit the tested process, execution uncertainty, financial capacity, and the cost of stopping. A loss limit cannot turn a negative-expectancy strategy into a positive one.')
      ], 'Define the measurement and the action; do not mistake a session rule for a guaranteed loss cap.', 'wait-trigger', 'Write a session loss rule and demonstrate a deliberate no-entry decision when remaining capacity is insufficient.', ['Include open P&L and costs if the stated rule requires them.', 'Specify what happens to existing positions and working orders at the boundary.']),
      L('risk-recovery-3', 'Return through evidence, not a recovery deadline', [
        S('Pause the behavior that caused the problem', 'After a control failure, the first objective is to stop repeating it. This may mean returning to simulation, reducing complexity, or pausing new risk while the account is reconciled. Do not increase exposure to recover a loss, repay a fee, or prove that the earlier decision was right.'),
        S('Use observable return criteria', 'Create a small practice plan that tests the specific repair. Examples include accurate quantity entry, confirmed protection, no duplicate submissions, and complete records. Passing these process checks supports the conclusion that the procedure worked in practice; it does not prove a strategy has an edge.'),
        S('Keep money needs outside the performance target', 'Money needed for living expenses or an emergency reserve should not become an urgent trading recovery goal. Review affordability separately from chart opportunity. A course badge, a run of paper wins, or a simulated payout does not establish professional readiness or replace product and account requirements.'),
        S('Write a staged decision', 'State the failure, the repair, the practice evidence required, and what would keep you paused. Do not set a calendar deadline that overrides missing evidence.', 'After duplicate orders, a fictional return plan requires ten paper order sequences with a unique order record, correct total quantity, and reconciled protection. If another duplicate appears, inspect the workflow and repeat the verification. Ten clean attempts validate that narrow procedure in that setting, not future profits.')
      ], 'A controlled return needs evidence that the failure was addressed, not a promise to win the money back.', 'review-trade', 'Write and review a narrow return-to-practice plan tied to one observable mistake. Keep its success criteria separate from profit.', ['State a measurable repair and a reason to remain paused.', 'Do not treat practice completion as a license or profit guarantee.'])
    ], [
      Q('A trade followed its written plan and lost within the modeled range. What is a sound review?', 'Record the loss and process adherence separately, then include it in the full sample.', ['Delete it because a good plan cannot lose.', 'Double the next size to make the record positive.', 'Rewrite the entry rule to fit the completed chart.'], 'A planned loss is still data. Outcome and process quality need separate records.'),
      Q('A profitable trade violated the quantity limit. How should it be recorded?', 'A profit with a process violation.', ['A perfect trade because it made money.', 'A reason to remove quantity limits.', 'No record because the error helped.'], 'Rewarding a rule violation only because it won hides the exposure that could harm a later trade.'),
      Q('A fictional $200 session limit includes closed net loss of $120 and an open loss of $55. What nominal room remains before further movement and costs?', '$25', ['$80', '$145', '$200'], '$200 − $120 − $55 = $25. This is a snapshot, not a guarantee that the open trade cannot lose more.'),
      Q('Which repair is most testable after duplicate orders?', 'Verify unique order IDs and total filled quantity before any replacement or protection change.', ['Try harder to be disciplined.', 'Use more leverage to recover the error.', 'Ignore timeouts when the chart looks attractive.'], 'A specific observable action can be practiced and audited. A general intention cannot show whether the failure was fixed.'),
      Q('What does completing a return-to-practice checklist establish?', 'The stated procedures were demonstrated in that practice setting.', ['A guarantee of the next live trade’s profit.', 'A professional trading license.', 'That living-expense money is now safe to trade.'], 'Process evidence has a defined scope. It does not establish future profitability, legal qualification, or personal financial capacity.')
    ]),
  ];

  const categories = {
    'risk-stop-evidence': 'Stops & evidence',
    'risk-leverage-margin': 'Leverage & margin',
    'risk-portfolio': 'Portfolio exposure',
    'risk-drawdown': 'Drawdown & survival',
    'risk-futures-forex': 'Futures & forex',
    'risk-options': 'Options obligations',
    'risk-short-crypto': 'Shorts & crypto',
    'risk-market-events': 'Gaps & liquidity',
    'risk-prop-rules': 'Prop evaluation rules',
    'risk-operations': 'Operations & fraud',
    'risk-research': 'Research integrity',
    'risk-recovery': 'Post-loss decisions'
  };
  let caseIndex = 0;
  function C(moduleId, lessonNumber, title, scenario, correct, distractors, explanation, sourceIds) {
    const index = caseIndex++;
    const answer = (index * 3 + 1) % 4;
    const choices = distractors.slice();
    choices.splice(answer, 0, correct);
    return {
      id: 'risk-case-' + String(index + 1).padStart(2, '0'),
      category: categories[moduleId], title, scenario, choices, answer, explanation,
      moduleId, lessonId: moduleId + '-' + lessonNumber, sourceIds
    };
  }
